queries.expression:
sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-frontend"}

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-backend"}

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-db"}

sum by (name) (
  irate(container_cpu_usage_seconds_total{id=~"/docker/.+",cpu="total", instance="cadvisor:8080", job="cadvisor"}[30s])
  * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
) and on(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata", name="leafy-minio"}

max by (name) (
  (
    container_memory_working_set_bytes{id=~"/docker/.+", instance="cadvisor:8080", job="cadvisor"}
    / (container_spec_memory_limit_bytes{id=~"/docker/.+", instance="cadvisor:8080", job="cadvisor"} > 0)
  ) * on(id) group_left(name) container_name_info{instance="pipeline:8000", job="pipeline-metadata"}
)

(
  sum by (name) (
    rate(container_network_receive_bytes_total{interface!="lo", id=~"/docker/.+", name!="", name=~"leafy-frontend|leafy-backend|leafy-db|leafy-minio", instance="cadvisor:8080", job="cadvisor"}[1m])
  )
)

(
  (
    sum without (interface) (
      rate(container_network_receive_bytes_total{interface!="lo", id="/", instance="cadvisor:8080", job="cadvisor"}[1m])
    )
  )
  unless on ()
  (count(container_network_receive_bytes_total{id=~"/docker/.+", instance="cadvisor:8080", job="cadvisor"}) > 0)
)

sum(count_over_time(
  {log_format="json", runtime="container", service="frontend"} | json | status >= 500 | __error__="" [1m]
))

sum(count_over_time(
  {log_format="json", runtime="container", service="frontend"} | json | status >= 400 and status < 500 | __error__="" [1m]
))

sum(count_over_time(
  {runtime="container", service="frontend"} |~ "(?i)(union.{0,3}select|or.{0,3}1=1|drop.{0,3}table|sleep\\(|extractvalue|information_schema|admin'--|and.{0,3}1=1)" [2m]
))
